import { expect, type Browser, type Page } from "@playwright/test";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
export const REPO = resolve(here, "../..");
export const DATA = resolve(here, ".data");

// The demo password is generated by scripts/dev_setup.py and never committed.
export function demoPassword(): string {
  if (process.env.E2E_PASSWORD) return process.env.E2E_PASSWORD;
  const line = readFileSync(resolve(REPO, ".env.e2e"), "utf8")
    .split("\n")
    .find((l) => l.startsWith("DEV_DEMO_PASSWORD="));
  if (!line) throw new Error(".env.e2e has no DEV_DEMO_PASSWORD; did the e2e backend start?");
  return line.slice("DEV_DEMO_PASSWORD=".length).trim();
}

export async function signIn(page: Page, username: string): Promise<void> {
  await page.goto("/");
  await page.getByLabel("Username").fill(username);
  await page.getByLabel("Password").fill(demoPassword());
  await page.getByRole("button", { name: "Sign in" }).click();
  await expect(page.getByRole("button", { name: "Sign out" })).toBeVisible();
}

// Each role gets its own browser context, exactly like two people on two machines.
export async function sessionFor(browser: Browser, username: string): Promise<Page> {
  const context = await browser.newContext();
  const page = await context.newPage();
  await signIn(page, username);
  return page;
}

export async function upload(page: Page, period: string): Promise<void> {
  await page.goto("/periods");
  await page.getByLabel("Reporting period").fill(period);
  await page.locator("#suppliers").setInputFiles(resolve(DATA, period, "suppliers.csv"));
  await page.locator("#invoices").setInputFiles(resolve(DATA, period, "invoices.csv"));
  await page.getByRole("button", { name: "Upload" }).click();
  await expect(page).toHaveURL(/\/versions\/[0-9a-f-]+$/);
}

export function catalogue(period: string): {
  expected_findings: Record<string, { rows: unknown[] }>;
  row_counts: { invoices: number; suppliers: number };
} {
  return JSON.parse(readFileSync(resolve(DATA, period, "catalogue.json"), "utf8"));
}
